import { inject, Injectable } from '@angular/core';
import { LocalStorageService } from '../local-storage/local-storage.service';
import { AuthData } from 'test-library-frankmd93';
import { BehaviorSubject, Observable } from 'rxjs';

interface AuthDataExtended extends AuthData {
  struttura?: {
    key: number;
    nmStruttura: string;
    dsStruttura: string;
  };
  tributo?: {
    key: number;
    nmStruttura: string;
    dsStruttura: string;
  };
  ufficio?: {
    key: number;
    nmStruttura: string;
    dsStruttura: string;
  };
}

@Injectable({ providedIn: 'root' })
export class AuthenticationService {
  private localStorageService = inject(LocalStorageService);
  private storageKey = 'auth';

  private authDataSubject = new BehaviorSubject<AuthDataExtended | null>(
    this.localStorageService.getItem<AuthDataExtended>(this.storageKey),
  );

  get struttura() {
    return this.authDataSubject.getValue()?.struttura;
  }

  get ufficio() {
    return this.authDataSubject.getValue()?.ufficio;
  }

  get tributo() {
    return this.authDataSubject.getValue()?.tributo;
  }

  /**
   * Salva i dati di autenticazione estesi nello storage locale.
   * @param {AuthDataExtended | null} value Oggetto `AuthDataExtended` o `null` per rimuovere i dati.
   */
  setData(value: AuthDataExtended | null): void {
    this.localStorageService.setItem(this.storageKey, value);
    this.authDataSubject.next(value);
  }

  /**
   * Salva l'ufficio di autenticazione nello storage.
   * @param {AuthDataExtended['ufficio'] | null} value Oggetto `AuthDataExtended` o `null` per rimuovere i dati.
   */
  setUfficio(value?: AuthDataExtended['ufficio']): void {
    const newData = this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
    if (!newData) {
      return;
    }
    newData.ufficio = value;
    this.localStorageService.setItem(this.storageKey, newData);
    this.authDataSubject.next(newData);
  }

  /**
   * Salva il tributo di autenticazione nello storage.
   * @param {AuthDataExtended['tributo'] | null} value Oggetto `AuthDataExtended` o `null` per rimuovere i dati.
   */
  setTributo(value?: AuthDataExtended['tributo']): void {
    const newData = this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
    if (!newData) {
      return;
    }
    newData.tributo = value;
    this.localStorageService.setItem(this.storageKey, newData);
    this.authDataSubject.next(newData);
  }

  /**
   * Salva la struttura di autenticazione nello storage locale.
   * @param {AuthDataExtended['struttura'] | null} value Oggetto `AuthDataExtended['struttura']` o `null` per rimuovere i dati.
   */
  setStruttura(value?: AuthDataExtended['struttura']): void {
    const newData = this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
    if (!newData) {
      return;
    }
    newData.struttura = value;
    this.localStorageService.setItem(this.storageKey, newData);
    this.authDataSubject.next(newData);
  }

  /**
   * Restituisce il token di autenticazione, se disponibile.
   * @returns {string | null | undefined} Il token di autenticazione, se disponibile, altrimenti null o undefined.
   */
  getToken(): string | null | undefined {
    return this.localStorageService.getItem<AuthDataExtended>(this.storageKey)?.token || null;
  }

  /**
   * Restituisce i dati di autenticazione salvati nello storage locale.
   * @returns {AuthDataExtended | null} I dati di autenticazione salvati nello storage locale, se disponibili, altrimenti null.
   */
  getData(): AuthDataExtended | null {
    return this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
  }

  /**
   * Ritorna un osservabile che emette i dati di autenticazione ogni volta che vengono modificati.
   * @returns {Observable<AuthDataExtended | null>} Un osservabile che emette i dati di autenticazione salvati nello storage locale, se disponibili, altrimenti null.
   */
  subscribeToAuthChanges(): Observable<AuthDataExtended | null> {
    return this.authDataSubject.asObservable();
  }
}

import { Component, Input } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router, RouterModule } from '@angular/router';
import { filter } from 'rxjs/operators';
import { CommonModule } from '@angular/common';
import { RemoteApplicationType, DataRoute } from 'test-library-frankmd93';

interface Breadcrumb {
  label: string;
  url: string;
}

@Component({
  standalone: true,
  imports: [RouterModule, CommonModule],
  selector: 'app-mf-breadcrumb',
  templateUrl: './breadcrumb.component.html',
  styleUrl: './breadcrumb.component.scss',
})
export class BreadcrumbComponent {
  @Input() id: string = '';
  @Input() applicationType: RemoteApplicationType = RemoteApplicationType.ANGULAR;
  @Input() breadcrumbs: Breadcrumb[] = [];
  minimumShouldEllipsis = 3;
  startExpandedFromIndex = 4;

  constructor(
    private router: Router,
    private activatedRoute: ActivatedRoute,
  ) {
    this.breadcrumbs = this.createBreadcrumbs(this.activatedRoute.root);
    this.router.events.pipe(filter((event) => event instanceof NavigationEnd)).subscribe(() => {
      this.breadcrumbs = this.createBreadcrumbs(this.activatedRoute.root);
      this.expandedFromIndex = Infinity;
    });
  }

  navigateTo(url: string, $event: Event) {
    $event.preventDefault();
    if (this.applicationType === RemoteApplicationType.REACT) {
      let navigationUrl = url;

      navigationUrl = url === '/pec-mailer' ? '/' : url;

      if (url === '/') {
        globalThis.location.href = '/';
        return;
      }

      const navigateToEvent = new CustomEvent('navigateTo', {
        detail: { url: navigationUrl },
      });
      document.dispatchEvent(navigateToEvent);
    } else {
      this.router.navigate([url]);
    }
  }

  private createBreadcrumbs(
    route: ActivatedRoute,
    url: string = '',
    breadcrumbs: Breadcrumb[] = [],
  ): Breadcrumb[] {
    const children = route.children;

    if (children.length === 0) {
      return breadcrumbs;
    }

    for (const child of children) {
      const routeConfig = child.routeConfig;
      let newUrl = url === '/' ? `/${routeConfig?.path}` : `${url}/${routeConfig?.path}`;
      newUrl = newUrl.replaceAll(/\/{2,}/g, '/');

      if ((routeConfig?.data as DataRoute)?.label) {
        breadcrumbs.push({
          label: (routeConfig?.data as DataRoute)?.label,
          url: newUrl,
        });
      }
      return this.createBreadcrumbs(child, newUrl, breadcrumbs);
    }

    return breadcrumbs;
  }
  trackByCrumb(_: number, crumb: { url: string }): string {
    return crumb.url;
  }

  expandedFromIndex = this.startExpandedFromIndex; // All collapsed by default

  shouldCollapse(index: number): boolean {
    // Show always first, last back to startExpandedFromIndex
    if (index === 0 || index > this.breadcrumbs.length - this.startExpandedFromIndex - 1)
      return false;
    return index < this.expandedFromIndex;
  }

  isExpandable(index: number): boolean {
    return this.shouldCollapse(index);
  }

  onExpand(index: number): void {
    this.expandedFromIndex = index;
  }
}

import { CommonModule } from '@angular/common';
import { AfterContentInit, Component, TemplateRef, Input } from '@angular/core';

export enum ProgressIndicatorEnum {
  dots = 'dots',
  bar = 'bar',
}

interface ProgressIndicatorProperties {
  showRatio: boolean;
  showPercentage: boolean;
}

interface ButtonProperties {
  label: string;
  onClick: (step: number, currentIndex?: number) => Promise<unknown>;
  disabled?: boolean;
}

type DotsIndicatorProperties = ProgressIndicatorProperties & { percentageLabel?: string };
type BarIndicatorProperties = ProgressIndicatorProperties & { ratioLabel?: string };

type BackActionProperties = ButtonProperties & { percentageLabel?: string };
type ForwardActionProperties = ButtonProperties & { ratioLabel?: string };

type ActionProperties = {
  backButton?: BackActionProperties;
  forwardButton?: ForwardActionProperties;
};

type ProgressIndicatorPropertiesType =
  | {
      barProps?: BarIndicatorProperties;
      type?: ProgressIndicatorEnum.bar;
    }
  | {
      dotsProps?: DotsIndicatorProperties;
      type?: ProgressIndicatorEnum.dots;
    };

@Component({
  selector: 'app-stepper',
  templateUrl: './stepper.component.html',
  imports: [CommonModule],
  standalone: true,
})
export class StepperComponent implements AfterContentInit {
  @Input() steps: { slot: number; percent: number; templateRef: TemplateRef<unknown> }[] = [];
  @Input() slotIndex!: number;
  @Input() dynamicPercentage = false;
  @Input() progressIndicatorProps: ProgressIndicatorPropertiesType = {
    type: ProgressIndicatorEnum.bar,
    barProps: {
      showRatio: true,
      showPercentage: true,
    },
  };
  @Input() actionProps: ActionProperties = {
    forwardButton: {
      label: '',
      onClick: () => new Promise(() => {}),
      disabled: false,
    },
  };
  @Input() controlled: boolean = false;
  get isBarType(): boolean {
    return this.progressIndicatorProps?.type === ProgressIndicatorEnum.bar;
  }

  get isDotsType(): boolean {
    return this.progressIndicatorProps?.type === ProgressIndicatorEnum.dots;
  }

  get showPercentage(): boolean | undefined {
    return this.progressIndicatorProps?.type === ProgressIndicatorEnum.dots
      ? this.progressIndicatorProps.dotsProps?.showPercentage
      : this.progressIndicatorProps?.type === ProgressIndicatorEnum.bar
        ? this.progressIndicatorProps.barProps?.showPercentage
        : false;
  }

  get showRatio() {
    if (this.progressIndicatorProps?.type === ProgressIndicatorEnum.dots) {
      return this.progressIndicatorProps.dotsProps?.showRatio;
    } else if (this.progressIndicatorProps?.type === ProgressIndicatorEnum.bar) {
      return this.progressIndicatorProps.barProps?.showRatio;
    } else {
      return false;
    }
  }

  templates!: { slot: number; percent: number; templateRef: TemplateRef<unknown> }[];

  ngAfterContentInit() {
    this.templates = this.steps
      ? this.steps.map((step) => ({
          percent: step.percent,
          slot: step.slot,
          templateRef: step.templateRef,
        }))
      : [];
    this.templates.sort((a, b) => a.slot - b.slot);
    if (!this.controlled) {
      this.slotIndex = this.templates[0]?.slot;
    }
  }

  get percentageSum(): number {
    return this.templates
      .filter((t) => t.slot <= this.slotIndex)
      .reduce((accumulator, t) => t.percent + accumulator, 0);
  }

  get currentIndex(): number {
    return this.templates.findIndex((t) => t.slot === this.slotIndex);
  }

  async back() {
    if (this.actionProps.backButton) {
      try {
        await this.actionProps.backButton.onClick(this.currentIndex, this.slotIndex);

        if (this.currentIndex > 0) {
          this.slotIndex = this.templates[this.currentIndex - 1].slot;
        }
      } catch (error) {
        console.error('Errore durante il back:', error);
      }
    }
  }

  async forward() {
    if (this.actionProps.forwardButton) {
      try {
        await this.actionProps.forwardButton.onClick(this.currentIndex, this.slotIndex);
        if (this.currentIndex < this.templates.length - 1) {
          this.slotIndex = this.templates[this.currentIndex + 1].slot;
        }
      } catch (error) {
        console.error('Errore durante il forward:', error);
      }
    }
  }

  trackByTemplate(_: number, template: { slot: number; templateRef: unknown }): number {
    return template.slot;
  }

  get progressBarWidthClass(): string {
    const width = Math.min(100, Math.max(0, Math.round(this.percentageSum)));
    return `progress-width-${width}`;
  }
}

import { Component, Input, OnInit, SimpleChanges, OnChanges } from '@angular/core';
import flatpickr from 'flatpickr';
import { PickerComponent } from '../picker/picker.component';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { DateTime } from 'luxon';
import { CommonModule } from '@angular/common';
import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';

type DateLike = DateTime | Date | string | null | undefined;
type DateLikeOrFunction = DateLike | (() => DateLike);

interface DateValidatorOptions {
  inclusive?: boolean; // default: true (>= min, <= max)
  format?: string; // default: 'dd/MM/yyyy HH:mm'
}

/** Helpers */
const defaultFormat = 'dd/MM/yyyy HH:mm';

const dateValidatorOptions = {
  inclusive: true,
  format: defaultFormat,
};

const resolve = (value?: DateLikeOrFunction): DateLike =>
  typeof value === 'function' ? (value as () => DateLike)() : value;

const toDateTime = (value?: DateLike, format = defaultFormat): DateTime | null => {
  if (!value) return null;
  if (DateTime.isDateTime(value)) return value.isValid ? value : null;
  if (value instanceof Date) return DateTime.fromJSDate(value);
  if (typeof value === 'string') {
    let dt = DateTime.fromISO(value);
    if (!dt.isValid) dt = DateTime.fromFormat(value, format);
    if (!dt.isValid) dt = DateTime.fromFormat(value, 'dd/MM/yyyy');
    return dt.isValid ? dt : null;
  }
  return null;
};

const parseControlValue = (value: DateTime | null, format = defaultFormat): DateTime | null => {
  if (typeof value === 'string') {
    let dt = DateTime.fromFormat(value, format);
    if (!dt.isValid) dt = DateTime.fromFormat(value, 'dd/MM/yyyy');
    return dt.isValid ? dt : null;
  }
  if (value instanceof Date) return DateTime.fromJSDate(value);
  if (DateTime.isDateTime(value)) return (value as DateTime).isValid ? value : null;
  return null;
};

const toMillisUTC = (dt: DateTime | null): number | null => (dt ? dt.toUTC().toMillis() : null);

/**
 * Validator che verifica che una DATA sia compresa tra
 * 01/01/{yearMin} e 31/12/{yearMax}.
 * - Se la data è assente o non valida → lascia ad altri validator (ritorna null).
 * - Se presente e valida → verifica i limiti (inclusivi di default).
 * @param {DateLikeOrFunction} min - La data di riferimento per il limite minimo
 * @param {DateValidatorOptions} options - Opzioni per il validator
 * @returns {(control: AbstractControl) => ValidationErrors | null} - Funzione di validazione
 */
export function minDateValidator(min: DateLikeOrFunction, options: DateValidatorOptions = {}) {
  const inclusive = options.inclusive ?? true;
  const fmt = options.format ?? defaultFormat;

  return (control: AbstractControl): ValidationErrors | null => {
    const value = control.value;
    if (value == null || value === '') return null; // lascia a required

    const parsed = parseControlValue(value, fmt);
    if (!parsed) return null; // lascia ad un validator "invalidDate"

    const minDT = toDateTime(resolve(min), fmt);
    if (!minDT) return null; // nessun limite

    const p = toMillisUTC(parsed);
    const m = toMillisUTC(minDT);
    if (p == null || m == null) return null;

    // errore se parsed < min (inclusivo) oppure parsed <= min (esclusivo)
    const invalid = inclusive ? p < m : p <= m;
    return invalid ? { minDate: { min: minDT } } : null;
  };
}

/**
 * Validator che verifica che una DATA sia compresa tra
 * 01/01/{yearMin} e 31/12/{yearMax}.
 * - Se la data è assente o non valida → lascia ad altri validator (ritorna null).
 * - Se presente e valida → verifica i limiti (inclusivi di default).
 * @param {DateLikeOrFunction} max - La data di riferimento per il limite massimo
 * @param {DateValidatorOptions} options - Opzioni per il validator
 * @returns {(control: AbstractControl) => ValidationErrors | null} - Funzione di validazione
 */
export function maxDateValidator(
  max: DateLikeOrFunction,
  options: DateValidatorOptions = {},
): ValidatorFn {
  const inclusive = options.inclusive ?? true;
  const fmt = options.format ?? defaultFormat;

  return (control: AbstractControl): ValidationErrors | null => {
    const value = control.value;
    if (value == null || value === '') return null;

    const parsed = parseControlValue(value, fmt);
    if (!parsed) return null;

    const maxDT = toDateTime(resolve(max), fmt);
    if (!maxDT) return null;

    const p = toMillisUTC(parsed);
    const M = toMillisUTC(maxDT);
    if (p == null || M == null) return null;

    // errore se parsed > max (inclusivo) oppure parsed >= max (esclusivo)
    const invalid = inclusive ? p > M : p >= M;
    return invalid ? { maxDate: { max: maxDT } } : null;
  };
}

export const validDate: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
  const value = control.value;
  if (!value) return null;
  if (typeof value === 'string') {
    const date = DateTime.fromFormat(value, 'dd/MM/yyyy');
    return date.isValid ? null : { invalidDate: true };
  }
  const isValid = value ? (value as DateTime)?.isValid : false;
  return isValid ? null : { invalidDate: true };
};

function defaultGetErrorMessage(formControl: FormControl): string | null {
  if (
    formControl?.errors?.['invalidDate'] &&
    formControl?.value &&
    !DateTime.fromFormat(formControl.value, 'dd/MM/yyyy').isValid
  ) {
    return 'Questo campo non è una data valida.';
  }
  if (formControl?.errors && formControl.errors['required']) {
    return 'Questo campo è obbligatorio.';
  }
  return null;
}
@Component({
  selector: 'app-rc-date-picker',
  standalone: true,
  templateUrl: './date-picker.component.html',
  imports: [PickerComponent, ReactiveFormsModule, CommonModule],
  styleUrls: ['./date-picker.component.scss'],
})
export class DatePickerComponent implements OnInit, OnChanges {
  @Input() placeholder: string = 'Seleziona una data';
  @Input() date: DateTime | null = null;
  @Input() formControl: FormControl = new FormControl();
  @Input() label!: string;
  @Input() width: string = '';
  @Input() class: string = 'active';
  @Input() disabled: boolean = false;
  @Input() id: string = 'sample-picker';
  @Input() minDate: DateTime | null = null;
  @Input() maxDate: DateTime | null = null;
  dateTime: DateTime | null = null;
  @Input() getErrorMessage: CallableFunction = defaultGetErrorMessage;
  @Input() required = false;
  format = 'dd/MM/yyyy';

  get errorMessage() {
    return this.getErrorMessage(this.formControl);
  }

  options: flatpickr.Options.Options = {
    mode: 'single',
    enableTime: false,
    dateFormat: 'd/m/Y',
  };

  ngOnInit() {
    this.updateDisabledState.bind(this);
    this.dateTime = this.date || null;
    this.options = {
      ...this.options,
      minDate: this.minDate?.toJSDate(),
      maxDate: this.maxDate?.toJSDate(),
    };
    if (this.formControl) {
      const validators = [];
      validators.push(validDate);
      if (this.minDate) {
        validators.push(minDateValidator(this.minDate, dateValidatorOptions));
      }
      if (this.maxDate) {
        validators.push(maxDateValidator(this.maxDate, dateValidatorOptions));
      }
      this.formControl.addValidators(validators);
    }
  }
  ngOnChanges(changes: SimpleChanges) {
    if (changes['disabled']) {
      this.updateDisabledState(this.formControl);
    }
  }

  private updateDisabledState(formControl: FormControl) {
    if (!formControl) {
      return;
    }
    if (this.disabled) {
      formControl.disable({ emitEvent: false });
    } else {
      formControl.enable({ emitEvent: false });
    }
  }
}

import { Component, Input, OnInit, SimpleChanges, OnChanges } from '@angular/core';
import flatpickr from 'flatpickr';
import { PickerComponent } from '../picker/picker.component';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { DateTime } from 'luxon';
import { CommonModule } from '@angular/common';
import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';

type DateLike = DateTime | Date | string | null | undefined;
type DateLikeOrFunction = DateLike | (() => DateLike);

interface DateValidatorOptions {
  inclusive?: boolean; // default: true (>= min, <= max)
  format?: string; // default: 'dd/MM/yyyy HH:mm'
}

/** Helpers */
const defaultFormat = 'dd/MM/yyyy HH:mm';

const dateValidatorOptions = {
  inclusive: true,
  format: defaultFormat,
};

const resolve = (value?: DateLikeOrFunction): DateLike =>
  typeof value === 'function' ? (value as () => DateLike)() : value;

const toDateTime = (value?: DateLike, format = defaultFormat): DateTime | null => {
  if (!value) return null;
  if (DateTime.isDateTime(value)) return value.isValid ? value : null;
  if (value instanceof Date) return DateTime.fromJSDate(value);
  if (typeof value === 'string') {
    let dt = DateTime.fromISO(value);
    if (!dt.isValid) dt = DateTime.fromFormat(value, format);
    if (!dt.isValid) dt = DateTime.fromFormat(value, 'dd/MM/yyyy');
    return dt.isValid ? dt : null;
  }
  return null;
};

const parseControlValue = (value: DateTime | null, format = defaultFormat): DateTime | null => {
  if (typeof value === 'string') {
    let dt = DateTime.fromFormat(value, format);
    if (!dt.isValid) dt = DateTime.fromFormat(value, 'dd/MM/yyyy');
    return dt.isValid ? dt : null;
  }
  if (value instanceof Date) return DateTime.fromJSDate(value);
  if (DateTime.isDateTime(value)) return (value as DateTime).isValid ? value : null;
  return null;
};

const toMillisUTC = (dt: DateTime | null): number | null => (dt ? dt.toUTC().toMillis() : null);

/** MIN DATE: richiede data >= min (default inclusivo) */
export function minDateValidator(min: DateLikeOrFunction, options: DateValidatorOptions = {}) {
  const inclusive = options.inclusive ?? true;
  const fmt = options.format ?? defaultFormat;

  return (control: AbstractControl): ValidationErrors | null => {
    const value = control.value;
    if (value == null || value === '') return null; // lascia a required

    const parsed = parseControlValue(value, fmt);
    if (!parsed) return null; // lascia ad un validator "invalidDate"

    const minDT = toDateTime(resolve(min), fmt);
    if (!minDT) return null; // nessun limite

    const p = toMillisUTC(parsed);
    const m = toMillisUTC(minDT);
    if (p == null || m == null) return null;

    // errore se parsed < min (inclusivo) oppure parsed <= min (esclusivo)
    const invalid = inclusive ? p < m : p <= m;
    return invalid ? { minDate: { min: minDT } } : null;
  };
}

/** ✅ MAX DATE: richiede data <= max (default inclusivo) */
export function maxDateValidator(
  max: DateLikeOrFunction,
  options: DateValidatorOptions = {},
): ValidatorFn {
  const inclusive = options.inclusive ?? true;
  const fmt = options.format ?? defaultFormat;

  return (control: AbstractControl): ValidationErrors | null => {
    const value = control.value;
    if (value == null || value === '') return null;

    const parsed = parseControlValue(value, fmt);
    if (!parsed) return null;

    const maxDT = toDateTime(resolve(max), fmt);
    if (!maxDT) return null;

    const p = toMillisUTC(parsed);
    const M = toMillisUTC(maxDT);
    if (p == null || M == null) return null;

    // errore se parsed > max (inclusivo) oppure parsed >= max (esclusivo)
    const invalid = inclusive ? p > M : p >= M;
    return invalid ? { maxDate: { max: maxDT } } : null;
  };
}

export const validDateTime: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
  const value = control.value;
  if (!value) return null;

  if (typeof value === 'string') {
    const date = DateTime.fromFormat(value, 'dd/MM/yyyy HH:mm');
    return date.isValid ? null : { invalidDate: true };
  }

  const isValid = (value as DateTime)?.isValid;
  return isValid ? null : { invalidDate: true };
};

function defaultGetErrorMessage(formControl: FormControl): string | null {
  if (
    formControl.errors?.['invalidDate'] &&
    formControl.value &&
    !DateTime.fromFormat(formControl.value, 'dd/MM/yyyy HH:mm').isValid
  ) {
    return 'Questo campo non è una data valida.';
  }

  if (formControl?.errors && formControl.errors['required']) {
    return 'Questo campo è obbligatorio.';
  }

  return null;
