  OnInit,
  ViewChildren,
  QueryList,
  ChangeDetectorRef,
} from '@angular/core';
import { CardWrapperComponent } from '../card-wrapper/card-wrapper.component';
import {
  FormArray,
  FormBuilder,
  FormControl,
  FormGroup,
  FormsModule,
  ReactiveFormsModule,
} from '@angular/forms';
import {
  faEye,
  faPenToSquare,
  faTrash,
  faEllipsisVertical,
