import { inject, Injectable } from '@angular/core';
import { AuthenticationService } from '../authentication/authentication.service';

@Injectable({
  providedIn: 'root',
})
export class AbilityService {
  private readonly authService = inject(AuthenticationService);

  has(ability: string): boolean {
    return this.authService.getData()?.user?.abilitazioni?.includes(ability) || false;
  }

  hasSome(abilities: string[]): boolean {
    return abilities.some((ab) => this.has(ab));
  }

  hasAll(abilities: string[]): boolean {
    return abilities.every((ab) => this.has(ab));
  }
}

import { inject, Injectable } from '@angular/core';
import { LocalStorageService } from '../local-storage/local-storage.service';
import { AuthData } from 'test-library-frankmd93';
import { BehaviorSubject, Observable } from 'rxjs';

interface AuthDataExtended extends AuthData {
  struttura?: {
    key: number;
    nmStruttura: string;
    dsStruttura: string;
  };
  tributo?: {
    key: number;
    nmStruttura: string;
    dsStruttura: string;
  };
  ufficio?: {
    key: number;
    nmStruttura: string;
    dsStruttura: string;
  };
}

@Injectable({ providedIn: 'root' })
export class AuthenticationService {
  private localStorageService = inject(LocalStorageService);
  private storageKey = 'auth';

  private authDataSubject = new BehaviorSubject<AuthDataExtended | null>(
    this.localStorageService.getItem<AuthDataExtended>(this.storageKey),
  );

  get struttura() {
    return this.authDataSubject.getValue()?.struttura;
  }

  get ufficio() {
    return this.authDataSubject.getValue()?.ufficio;
  }

  get tributo() {
    return this.authDataSubject.getValue()?.tributo;
  }

  /**
   * Salva i dati di autenticazione estesi nello storage locale.
   * @param {AuthDataExtended | null} value Oggetto `AuthDataExtended` o `null` per rimuovere i dati.
   */
  setData(value: AuthDataExtended | null): void {
    this.localStorageService.setItem(this.storageKey, value);
    this.authDataSubject.next(value);
  }

  /**
   * Salva l'ufficio di autenticazione nello storage.
   * @param {AuthDataExtended['ufficio'] | null} value Oggetto `AuthDataExtended` o `null` per rimuovere i dati.
   */
  setUfficio(value?: AuthDataExtended['ufficio']): void {
    const newData = this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
    if (!newData) {
      return;
    }
    newData.ufficio = value;
    this.localStorageService.setItem(this.storageKey, newData);
    this.authDataSubject.next(newData);
  }

  /**
   * Salva il tributo di autenticazione nello storage.
   * @param {AuthDataExtended['tributo'] | null} value Oggetto `AuthDataExtended` o `null` per rimuovere i dati.
   */
  setTributo(value?: AuthDataExtended['tributo']): void {
    const newData = this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
    if (!newData) {
      return;
    }
    newData.tributo = value;
    this.localStorageService.setItem(this.storageKey, newData);
    this.authDataSubject.next(newData);
  }

  /**
   * Salva la struttura di autenticazione nello storage locale.
   * @param {AuthDataExtended['struttura'] | null} value Oggetto `AuthDataExtended['struttura']` o `null` per rimuovere i dati.
   */
  setStruttura(value?: AuthDataExtended['struttura']): void {
    const newData = this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
    if (!newData) {
      return;
    }
    newData.struttura = value;
    this.localStorageService.setItem(this.storageKey, newData);
    this.authDataSubject.next(newData);
  }

  /**
   * Restituisce il token di autenticazione, se disponibile.
   * @returns {string | null | undefined} Il token di autenticazione, se disponibile, altrimenti null o undefined.
   */
  getToken(): string | null | undefined {
    return this.localStorageService.getItem<AuthDataExtended>(this.storageKey)?.token || null;
  }

  /**
   * Restituisce i dati di autenticazione salvati nello storage locale.
   * @returns {AuthDataExtended | null} I dati di autenticazione salvati nello storage locale, se disponibili, altrimenti null.
   */
  getData(): AuthDataExtended | null {
    return this.localStorageService.getItem<AuthDataExtended>(this.storageKey);
  }

  /**
   * Ritorna un osservabile che emette i dati di autenticazione ogni volta che vengono modificati.
   * @returns {Observable<AuthDataExtended | null>} Un osservabile che emette i dati di autenticazione salvati nello storage locale, se disponibili, altrimenti null.
   */
  subscribeToAuthChanges(): Observable<AuthDataExtended | null> {
    return this.authDataSubject.asObservable();
  }
}

import { inject, Injectable } from '@angular/core';
import { AuthenticationService } from '../authentication/authentication.service';

@Injectable({
  providedIn: 'root',
})
export class AuthorizationService {
  private readonly authService = inject(AuthenticationService);

  filterByAuthorization<T>(
    items: T[],
    authorizationsKey: keyof T = 'authorizations' as keyof T,
  ): T[] {
    const authData = this.authService.getData();

    console.debug('authData', authData, items);

    if (!items || !authData?.user?.abilitazioni) {
      return [];
    }

    const userAbilitazioni = authData.user.abilitazioni;

    return items.filter((item) => {
      const auths = item[authorizationsKey];
      if (!Array.isArray(auths)) return false;

      return auths.some((auth) => typeof auth === 'string' && userAbilitazioni.includes(auth));
    });
  }
}

import { Injectable } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class BaseHrefService {
  get baseUrl(): string {
    const selector = document.querySelector('base')?.getAttribute('href') || '';
    return selector === '/' ? '' : selector;
  }
}

import { Injectable } from '@angular/core';
import { LoggerArguments } from '../types/logger-arguments';
import { LoggerChannelInterface } from '../types/logger-channel-interface';

@Injectable()
export class ConsoleLoggerChannel implements LoggerChannelInterface {
  /**
   * @inheritDoc
   */
  log(message?: string, ...arguments_: LoggerArguments[]): void {
    console.log(message, ...arguments_);
  }

  /**
   * @inheritDoc
   */
  debug(message?: string, ...arguments_: LoggerArguments[]): void {
    console.debug(message, ...arguments_);
  }

  /**
   * @inheritDoc
   */
  info(message?: string, ...arguments_: LoggerArguments[]): void {
    console.info(message, ...arguments_);
  }

  /**
   * @inheritDoc
   */
  warn(message?: string, ...arguments_: LoggerArguments[]): void {
    console.warn(message, ...arguments_);
  }

  /**
   * @inheritDoc
   */
  error(message?: string, ...arguments_: LoggerArguments[]): void {
    console.error(message, ...arguments_);
  }
}

import { ErrorHandler, inject, Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { HttpErrorResponse } from '@angular/common/http';

@Injectable({
  providedIn: 'root',
})
export class GlobalErrorHandler implements ErrorHandler {
  router = inject(Router);

  handleError(error: unknown): void {
    console.error('Errore globale catturato', error);
    if (error instanceof HttpErrorResponse) {
      console.warn('Errore HTTP:', error.message);
      return;
    }
    if (this.router) {
      this.router.navigate(['/error-page']).catch((error_) => {
        console.error('Errore durante la navigazione:', error_);
      });
    } else {
      console.warn('Router non disponibile per la navigazione.');
    }
  }
}

import { concatMap, retryWhen, delay, observeOn, map } from 'rxjs/operators';
import { of, throwError, Observable, asyncScheduler } from 'rxjs';
import {
  HttpClient,
  HttpEventType,
  HttpRequest,
  HttpResponse,
  HttpStatusCode,
} from '@angular/common/http';
import { Injectable } from '@angular/core';
import { AbstractRemoteCall, RemoteCallInterface } from 'test-library-frankmd93';
import { ObjectExtensionsService } from '@mf/core/utils/object-extensions/object-extensions.service';
import { RemoteCallCacheService } from '../cache/remote-call-cache.service';
import { HttpData } from 'test-library-frankmd93';

/**
 * @deprecated to pass in the test-library
 */
type HttpDataWithReportProgress<TViewModel, TModel> = HttpData<TViewModel, TModel> & {
  call: RemoteCallInterface<TViewModel, TModel> & { reportProgress?: boolean };
};

/**
 * @deprecated pass it to test-library
 */
abstract class RemoteCallWithReportProgress<T, R> extends AbstractRemoteCall<T, R> {
  reportProgress?: boolean;
}

@Injectable({ providedIn: 'root' })
export class HttpClientService {
  private constructor(
    readonly httpClient: HttpClient,
    readonly objectExtensionsService: ObjectExtensionsService,
    readonly remoteCallCache?: RemoteCallCacheService,
  ) {}

  /**
   * Executes the remote call.
   */
  execute<TViewModel, TModel>(
    remoteCall: RemoteCallWithReportProgress<TViewModel, TModel>,
  ): Observable<TViewModel | TModel | HttpResponse<TModel> | null> {
    // Check if a response is already available in the cache and just returns it
    // if found.
    const cachedResponseEntry = this.remoteCallCache?.get<TViewModel, TModel>(remoteCall);
    if (cachedResponseEntry) {
      // NOTE: We get a response from the cache, in order to make
      // Angular change detection working fine we provide the cached
      // response asynchrounsly avoiding changing the value while
      // the detection is running!
      return of(cachedResponseEntry).pipe(observeOn(asyncScheduler)) as Observable<
        TViewModel | TModel
      >;
    }

    return (
      of(remoteCall)
        // Create an http request from the remote call.
        .pipe(
          map((call: RemoteCallWithReportProgress<TViewModel, TModel>) => {
            const httpRequest = new HttpRequest(
              call.method,
              `${call.baseUrl}${call.relativePath}`,
              call.getBody(),
              {
                withCredentials: call.withCredentials,
                responseType: call.responseType,
                params: call.getQuery(),
                headers: call.getHeaders(),
                reportProgress: call.reportProgress || false,
                context: call.getContext(),
              },
            );

            return { httpRequest, call } as HttpData<TViewModel, TModel>;
          }),
          // Performs the http request and propagate the remote call.
          concatMap(({ httpRequest, call }: HttpDataWithReportProgress<TViewModel, TModel>) => {
            let request$ = this.httpClient.request(httpRequest.method, httpRequest.url, {
              body: httpRequest.body,
              headers: httpRequest.headers,
              reportProgress: httpRequest.reportProgress,
              observe: call.reportProgress ? 'events' : 'response',
              params: httpRequest.params,
              responseType: httpRequest.responseType,
              withCredentials: httpRequest.withCredentials,
              context: httpRequest.context,
            });

            // Check if we need to setup a request retry.
            const shouldSetupRequestRetry =
              Number.isFinite(call.retryAttemptCount) && call.retryAttemptCount > 0;
            if (shouldSetupRequestRetry) {
              request$ = request$.pipe(
                retryWhen((notifiers: Observable<HttpResponse<TModel>>) =>
                  notifiers.pipe(
                    concatMap((response: HttpResponse<TModel>, index: number) => {
                      // If the all the attempts has been tried or the request is not failed with status code zero forward the error...
                      if (!response || response.status !== 0 || index > call.retryAttemptCount) {
                        return throwError(response);
                      }
                      // ...otherwise execute the next attempt after a specified amount of time.
                      return of(response).pipe(delay(call.retryDelay));
                    }),
                  ),
                ),
              );
            }

            // Finally propagate the remote call along with the request stream.
            return request$.pipe(
              map((httpResponse: HttpResponse<TModel>) => ({
                httpResponse,
                call,
              })),
            );
          }),
          // Finally let's perform the mapping to get the response slice that's actually needed.
          map(({ httpResponse, call }) => {
            console.log(httpResponse);
            /**
             * Da rifattorizzare
             * al momento se progress ti dà la response solo se è ok
             */
            if (call.reportProgress) {
              if (
                (httpResponse.type as HttpEventType) === HttpEventType.ResponseHeader &&
                httpResponse.status !== HttpStatusCode.Ok
              ) {
                return null;
              }
              return httpResponse;
            }

            const model = call.contentProperty
              ? this.objectExtensionsService.getObjectValue<TModel>(
                  httpResponse,
                  call.contentProperty,
                )
              : (httpResponse as HttpResponse<TModel>);

            // Update the remote calls cache.
            if (this.remoteCallCache) {
              this.remoteCallCache.put<TViewModel, TModel>(call, model as TModel);
            }

            return (
              remoteCall.trasformer?.toViewModel(model as TModel) || (model as HttpResponse<TModel>)
            );
          }),
        )
    );
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { distinctUntilChanged, map, shareReplay } from 'rxjs/operators';

/**
 * Keep track of the consumers that want to move the application in a
 * loading state.
 */
@Injectable({
  providedIn: 'root',
})
export class HttpLoadingService {
  /**
   * An internal counter maintaining the number of consumers that want
   * to move the app in a loading state.
   */
  private callers: BehaviorSubject<number> = new BehaviorSubject(0);

  /**
   * The loading stream.
   */
  get loading$(): Observable<boolean> {
    return this.callers.asObservable().pipe(
      map((callers: number) => callers > 0),
      distinctUntilChanged(),
      shareReplay(1),
    );
  }

  /**
   * Set the loading state.
   */
  setLoading(): void {
    const callers = this.callers.getValue();
    this.callers.next(callers + 1);
  }

  /**
   * Unset the loading state.
   */
  unsetLoading(): void {
    const callers = this.callers.getValue();

    if (callers === 0) {
      return;
    }

    this.callers.next(callers - 1);
  }
}

