import { Injectable } from '@angular/core';

/**
 * Provides a set of utilities method to interact with object-like values.
 */
@Injectable({ providedIn: 'root' })
export class ObjectExtensionsService {
  /**
   * Traverses the provided object to get the value bound
   * to the given path.
   */
  getObjectValue<T>(object: unknown, key?: string, defaultValue?: T): T {
    if (typeof key !== 'string') {
      return defaultValue as T;
    }

    if (typeof object !== 'object' || object === null) {
      return defaultValue as T;
    }

    // Splits the request key.
    let path = key.split('.');

    // Checks if it is an empty string.
    if (path.length === 0) {
      return defaultValue as T;
    }

    let data = object as Record<string, unknown>;

    let properties = Object.keys(data);

    // Reverses it to use the iterative algorithm. We use pop().
    path = path.reverse();

    // Iterates over the defined path.
    while (path.length > 0) {
      // Pop the path.
      const currentKey = path.pop();
      // Gets the data corresponding property of the current path.
      const currentProperty = properties.find((value: string) => currentKey === value);

      // If it doesn't exists return the default value.
      if (!currentProperty) {
        return defaultValue as T;
      }

      // Move a level down by getting the object of the next level.
      data = (data as Record<string, Record<string, unknown>>)[currentProperty];

      // If it is the last path we have, we are done.
      if (path.length === 0) {
        return !data && defaultValue ? defaultValue : (data as unknown as T);
      }

      // Otherwise we need to get the keys and iterate again.
      properties = Object.keys(data);
    }

    return defaultValue as T;
  }
}

import { Injectable } from '@angular/core';
import {
  RemoteCallInterface,
  RemoteCallCacheEntry,
  AbstractRemoteCallCache,
} from 'test-library-frankmd93';

@Injectable({ providedIn: 'root' })
export class RemoteCallCacheService extends AbstractRemoteCallCache {
  /**
   * The local cache providing for a given request url (with params)
   * the corresponding parsed response.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private readonly cache = new Map<string, RemoteCallCacheEntry<any>>();

  /**
   * Determines if for the given request is available a cached response.
   */
  has<TViewModel, TModel>(remoteCall: RemoteCallInterface<TViewModel, TModel>): boolean {
    const key = this.getRequestIdentifier(remoteCall);
    return this.cache.has(key);
  }

  /**
   * Gets the cached entry in the map for the given request.
   */
  get<TViewModel, TModel>(remoteCall: RemoteCallInterface<TViewModel, TModel>): TModel {
    const requestKey = this.getRequestIdentifier(remoteCall);

    const cachedEntry = this.cache.get(requestKey);
    if (!cachedEntry) {
      return null as TModel;
    }

    const isExpired = cachedEntry.lastRead + cachedEntry.maxAge < Date.now();
    return isExpired ? (null as TModel) : cachedEntry.response;
  }

  /**
   * Puts a new cached response for the given request.
   */
  put<TViewModel, TModel>(
    remoteCall: RemoteCallInterface<TViewModel, TModel>,
    response: TModel,
  ): void {
    if (!remoteCall.maxAge) {
      this.flush();
      return;
    }

    const requestKey = this.getRequestIdentifier(remoteCall);
    const entry: RemoteCallCacheEntry<TModel> = {
      response,
      identifier: requestKey,
      lastRead: Date.now(),
      maxAge: remoteCall.maxAge,
    };

    // Update and flush the cache.
    this.cache.set(requestKey, entry as RemoteCallCacheEntry<TModel>);
    this.flush();
  }

  /**
   * Founds all expired entry and deletes them from the cache.
   */
  flush(): void {
    this.cache.forEach((entry) => {
      const isEntryExpired = entry.lastRead + entry.maxAge < Date.now();

      if (isEntryExpired) {
        this.cache.delete(entry.identifier);
      }
    });
  }

  /**
   * Gets the unique key used as idenitifier to store
   * a cached response for the given remote call.
   */
  private getRequestIdentifier<TViewModel, TModel>(
    remoteCall: RemoteCallInterface<TViewModel, TModel>,
  ): string {
    const remoteCallUrl = `${remoteCall.getQuery}${remoteCall.relativePath}`;
    const stringifiedParameters = remoteCall.getQuery().toString();

    return stringifiedParameters ? `${remoteCallUrl}?${stringifiedParameters}` : remoteCallUrl;
  }
}

import { Injectable, OnDestroy } from '@angular/core';
import { Subject, BehaviorSubject, fromEvent } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { MediaBreakpointEnum, mediaBreakpoints } from 'test-library-frankmd93';

@Injectable({
  providedIn: 'root',
})
export class ResponsiveService implements OnDestroy {
  public screenWidth$: BehaviorSubject<number> = new BehaviorSubject(0);
  public mediaBreakpoint$: BehaviorSubject<MediaBreakpointEnum> =
    new BehaviorSubject<MediaBreakpointEnum>(MediaBreakpointEnum.MD);
  private unsubscriber$: Subject<null> = new Subject();

  constructor() {
    this.init();
  }

  init() {
    this.setScreenWidth(window.innerWidth);
    this.setMediaBreakpoint(window.innerWidth);
    fromEvent(globalThis, 'resize')
      .pipe(takeUntil(this.unsubscriber$))
      .subscribe((event: Event) => {
        const target = event.target as Window;
        if (target) {
          this.setScreenWidth(target.innerWidth);

          /*
            ? 13/10/2025 
            ? al resize di qualsiasi componente, 
            ? questo si "ricarica", ricominciando il suo lifecycle 
            ? e richiamando tutte le api del lifecycle.
            ? Per il resize penso sia meglio usare la media query di css
          */
          // this.setMediaBreakpoint(target.innerWidth);
        }
      });
  }

  ngOnDestroy() {
    this.unsubscriber$.next(null);
    this.unsubscriber$.complete();
  }

  private setScreenWidth(width: number): void {
    this.screenWidth$.next(width);
  }

  private setMediaBreakpoint(width: number): void {
    for (const [breakpoint, sizes] of Object.entries(mediaBreakpoints)) {
      if (width >= sizes.minSize && width < sizes.maxSize) {
        this.mediaBreakpoint$.next(breakpoint as MediaBreakpointEnum);
        return;
      }
    }
  }
}

