import { inject, Injectable } from '@angular/core';
import { CanActivate, Router, UrlTree } from '@angular/router';
import { Observable } from 'rxjs';
import { AuthenticationService } from './authentication.service';

@Injectable({
  providedIn: 'root',
})
export class AuthenticationGuard implements CanActivate {
  private readonly authService = inject(AuthenticationService);

  constructor(private router: Router) {}

  canActivate(): boolean | UrlTree | Observable<boolean | UrlTree> | Promise<boolean | UrlTree> {
    const token = this.authService.getToken();

    if (token) {
      return true;
    }

    // Redirect to login (or change route as needed)
    return this.router.createUrlTree(['/autenticazione/login']);
  }
}

import { inject, Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivateChild, Data, UrlTree } from '@angular/router';
import { Observable } from 'rxjs';
import { AuthenticationService } from '../authentication/authentication.service';
import { BaseHrefService } from '../base-href/base-href.service';

type DataRoute = Data & { authenticated?: boolean };

const useTrueIAM = '&useTrueIAM=true';

@Injectable({
  providedIn: 'root',
})
export class AuthenticationIAMGuard implements CanActivateChild {
  private readonly authService = inject(AuthenticationService);

  private readonly baseHrefService = inject(BaseHrefService);

  // manca codice ambito e applicazione
  private iamLocation = '/msAuth/api/v1/autenticazione/loginIAM';

  setIamLocation(iamLocation: string) {
    this.iamLocation = iamLocation;
  }

  canActivateChild(
    childRoute: ActivatedRouteSnapshot,
  ): boolean | UrlTree | Observable<boolean | UrlTree> | Promise<boolean | UrlTree> {
    const token = this.authService.getToken();

    // se la rotta non è da autenticare bypasso il redirect
    if (!(childRoute.data as DataRoute)?.authenticated) {
      return true;
    }

    // se la rotta è da autenticare e ho il token bypasso il redirect
    if ((childRoute.data as DataRoute)?.authenticated && token) {
      return true;
    }

    globalThis.location.href = this.baseHrefService.baseUrl
      ? this.iamLocation + useTrueIAM
      : this.iamLocation;

    return false;
  }
}

import { Injectable, inject } from '@angular/core';
import {
  ActivatedRouteSnapshot,
  CanActivate,
  CanActivateChild,
  GuardResult,
  MaybeAsync,
  Router,
  RouterStateSnapshot,
  UrlTree,
} from '@angular/router';
import { Observable } from 'rxjs';
import { AuthenticationService } from '../authentication/authentication.service';

@Injectable({
  providedIn: 'root',
})
export class AuthorizationGuard implements CanActivate, CanActivateChild {
  private router = inject(Router);

  private readonly authService = inject(AuthenticationService);

  canActivate(
    route: ActivatedRouteSnapshot,
  ): boolean | UrlTree | Observable<boolean | UrlTree> | Promise<boolean | UrlTree> {
    console.debug('route', route);
    const userAbilitazioni = this.authService?.getData()?.user?.abilitazioni ?? [];
    const requiredAuthorizations: string[] = route?.data['authorizations'] || [];

    const hasAuth = requiredAuthorizations.some((auth) => userAbilitazioni.includes(auth));

    if (hasAuth) {
      return true;
    }
    // Redirect to login (or change route as needed)
    return this.router.createUrlTree(['/']);
  }

  canActivateChild(
    childRoute: ActivatedRouteSnapshot,
    state: RouterStateSnapshot,
  ): MaybeAsync<GuardResult> {
    console.debug('childRoute', childRoute, state);
    if (
      !childRoute?.data['authorizations'] &&
      !(childRoute.children || [])[0]?.data['authorizations']
    ) {
      return true;
    }
    if (childRoute?.data['authorizations']) {
      return this.canActivate(childRoute);
    }
    return this.canActivate(childRoute.children[0]);
  }
}

