import { Singleton } from '@mf/core/utils/singleton';
import { BaseCustomEvent } from 'test-library-frankmd93';

type ListenerReference = {
  original: <T, R>(event: CustomEvent<BaseCustomEvent<T>>) => Promise<R> | Promise<void>;
  wrapped: EventListener;
};

export class EventBus extends Singleton {
  private readonly bus = new EventTarget();
  private listenersMap = new Map<string, ListenerReference[]>();
  private replyMap = new Map<string, boolean>();

  public addCustomEventListener<T, R>(
    eventName: string,
    handler: (event: CustomEvent<BaseCustomEvent<T>>) => Promise<R> | Promise<void>,
  ): void {
    const wrappedHandler: EventListener = async (event: Event) => {
      const customEvent = event as CustomEvent<BaseCustomEvent<T>>;
      const result = await handler(customEvent);

      if (customEvent.detail.reply) {
        this.bus.dispatchEvent(
          new CustomEvent<R>(`reply:${eventName}`, {
            detail: result as R,
          }),
        );
      }
    };

    const listeners = this.listenersMap.get(eventName) ?? [];
    listeners.push({
      original: handler as <T, R>(
        event: CustomEvent<BaseCustomEvent<T>>,
      ) => Promise<R> | Promise<void>,
      wrapped: wrappedHandler,
    });

    this.listenersMap.set(eventName, listeners);
    this.bus.addEventListener(eventName, wrappedHandler);
  }

  public removeCustomEventListener(eventName: string): void {
    const listeners = this.listenersMap.get(eventName);
    if (listeners) {
      for (const reference of listeners) {
        this.bus.removeEventListener(eventName, reference.wrapped);
      }
      this.listenersMap.delete(eventName);
    }
  }

  public dispatchCustomEvent<T, R>(event: BaseCustomEvent<T>): Promise<void | R> {
    const eventName = event.eventName;

    // Caso 1: broadcast, nessuna risposta attesa
    if (!event.reply) {
      const customEvent = new CustomEvent<BaseCustomEvent<T>>(eventName, {
        detail: {
          ...event,
          payload: {
            useTimer: true,
            ...event.payload,
          },
        },
      });
      this.bus.dispatchEvent(customEvent);
      return Promise.resolve();
    }

    // Caso 2: richiesta con attesa risposta
    if (this.replyMap.has(eventName)) {
      return Promise.reject(
        new Error(
          `Un evento con reply:true è già in attesa per "${eventName}", si può processare un evento reply:true alla volta.`,
        ),
      );
    }

    this.replyMap.set(eventName, true);

    return new Promise<R>((resolve) => {
      const replyHandler = (replyEvent: CustomEvent<R>) => {
        this.replyMap.delete(eventName);
        resolve(replyEvent.detail);
      };

      this.bus.addEventListener(`reply:${eventName}`, replyHandler as EventListener, {
        once: true,
      });

      const eventWithReply = new CustomEvent<BaseCustomEvent<T>>(eventName, {
        detail: {
          ...event,
          payload: {
            useTimer: true,
            ...event.payload,
          },
        },
      });

      this.bus.dispatchEvent(eventWithReply);
    });
  }
}

export type RowSpanMap<T> = Partial<Record<Extract<keyof T, string>, number>>;

export class GroupByTableHelper {
  /**
   * Costruisce una chiave di raggruppamento per una riga,
   * combinando i valori delle colonne indicate in groupBy.
   */
  static buildGroupKey<T>(row: T, groupBy: Array<Extract<keyof T, string>>): string {
    // Usa un separatore per ridurre il rischio di sovrapposizioni
    // tra valori concatenati (es. ["1","23"] vs ["12","3"])
    return groupBy.map((k) => String(row[k] ?? '')).join('␟');
  }

  /**
   * Raggruppa le righe rendendo contigue quelle che condividono la stessa chiave
   *  di grouping (groupBy) per permettere il corretto funzionamento del rowspan
   */
  static groupRowsForRowspan<T>(rows: T[], groupBy: Array<Extract<keyof T, string>>): T[] {
    if (rows.length === 0 || groupBy?.length === 0) return rows;

    // Mappa: chiave di gruppo - righe appartenenti a quel gruppo
    const rowGroup = new Map<string, T[]>();
    // Tiene traccia dell’ordine di comparsa dei gruppi
    const groupOrder: string[] = [];

    // Distribuisce le righe nei rispettivi gruppi
    for (const row of rows) {
      // Costruisce la chiave di raggruppamento
      const key = this.buildGroupKey(row, groupBy);

      // Se è la prima volta che incontra questa chiave
      // inizializza il gruppo e ne registra l'ordine
      if (!rowGroup.has(key)) {
        rowGroup.set(key, []);
        groupOrder.push(key);
      }

      // Inserisce la riga nel gruppo corrispondente
      rowGroup.get(key)!.push(row);
    }

    // Ricompone l'array finale seguendo l'ordine dei gruppi e l'ordine interno di ogni gruppo
    const result: T[] = [];
    for (const key of groupOrder) {
      result.push(...(rowGroup.get(key) ?? []));
    }

    return result;
  }

  /**
   * Costruisce la mappa dei rowspan per il rendering di una tabella raggruppata
   *
   * Per ciascun livello di `groupBy`, identifica blocchi contigui di righe
   * con lo stesso valore e assegna:
   * - il rowspan corretto alla prima riga del blocco
   * - 0 alle righe successive
   *
   * Nota: richiede che le righe siano già ordinate per `groupBy`.
   *
   * @param rows lista dati in ingresso
   * @param groupBy array di chiavi di colonne da raggruppare
   * @returns un array di oggetti con la mappa dei rowspan dove
   * spans[i][col] rappresenta il valore di rowspan da applicare alla cella
   *   della riga i per la colonna `col`
   */
  static calcRowSpans<T>(rows: T[], groupBy: Array<Extract<keyof T, string>>): RowSpanMap<T>[] {
    // Inizializza una rowspan vuota per ogni riga
    const spans: RowSpanMap<T>[] = rows.map(() => ({}));

    // Se non ci sono dati o colonne nel groupBy ritorna la struttura vuota
    if (rows.length === 0 || groupBy?.length === 0) return spans;

    // Applica il groupBy livello per livello (es. primo elemento, poi secondo, ecc.)
    for (let level = 0; level < groupBy.length; level++) {
      const groupColumn = groupBy[level];
      let startIndex = 0;

      while (startIndex < rows.length) {
        // Trova l'indice della prima row che non matcha con il gruppo
        const endIndex = this.findBlockEndIndex(rows, groupBy, groupColumn, level, startIndex);

        // Stabilisce la grandezza del gruppo
        const groupSize = endIndex - startIndex;

        // Applica alla prima riga del gruppo lo span corretto e alle altre lo imposta a 0
        spans[startIndex][groupColumn] = groupSize;
        for (let index = startIndex + 1; index < endIndex; index++) {
          spans[index][groupColumn] = 0;
        }

        startIndex = endIndex;
      }
    }

    return spans;
  }

  /**
   * Trova l’indice della riga successiva a quella finale delle righe da raggruppare
   */
  private static findBlockEndIndex<T>(
    rows: T[],
    groupBy: Array<Extract<keyof T, string>>,
    groupColumn: Extract<keyof T, string>,
    level: number,
    startIndex: number,
  ): number {
    const startRow = rows[startIndex];
    let index = startIndex + 1;

    // Continua finché il prefisso di grouping (livelli precedenti) è uguale
    // e il valore della colonna corrente è uguale
    while (
      index < rows.length &&
      this.hasSamePrefix(startRow, rows[index], groupBy, level) &&
      rows[index][groupColumn] === startRow[groupColumn]
    ) {
      index++;
    }

    return index;
  }

  /**
   * Verifica se due righe condividono lo stesso prefisso di grouping.
   *
   * Esempio:
   * groupBy = ['foglio', 'numero']
   * - livello 0 - nessun prefisso - sempre true
   * - livello 1 - confronta solo 'foglio'
   */
  private static hasSamePrefix<T>(
    a: T,
    b: T,
    groupBy: Array<Extract<keyof T, string>>,
    level: number,
  ): boolean {
    for (let index = 0; index < level; index++) {
      const col = groupBy[index];
      if (a[col] !== b[col]) {
        return false;
      }
    }
    return true;
  }
}

import { concatMap, retryWhen, delay, observeOn, map } from 'rxjs/operators';
import { of, throwError, Observable, asyncScheduler } from 'rxjs';
import {
  HttpClient,
  HttpEventType,
  HttpRequest,
  HttpResponse,
  HttpStatusCode,
} from '@angular/common/http';
import { Injectable } from '@angular/core';
import { AbstractRemoteCall, RemoteCallInterface } from 'test-library-frankmd93';
import { ObjectExtensionsService } from '@mf/core/utils/object-extensions/object-extensions.service';
import { RemoteCallCacheService } from '../cache/remote-call-cache.service';
import { HttpData } from 'test-library-frankmd93';

/**
 * @deprecated to pass in the test-library
 */
type HttpDataWithReportProgress<TViewModel, TModel> = HttpData<TViewModel, TModel> & {
  call: RemoteCallInterface<TViewModel, TModel> & { reportProgress?: boolean };
};

/**
 * @deprecated pass it to test-library
 */
abstract class RemoteCallWithReportProgress<T, R> extends AbstractRemoteCall<T, R> {
  reportProgress?: boolean;
}

@Injectable({ providedIn: 'root' })
export class HttpClientService {
  private constructor(
    readonly httpClient: HttpClient,
    readonly objectExtensionsService: ObjectExtensionsService,
    readonly remoteCallCache?: RemoteCallCacheService,
  ) {}

  /**
   * Executes the remote call.
   */
  execute<TViewModel, TModel>(
    remoteCall: RemoteCallWithReportProgress<TViewModel, TModel>,
  ): Observable<TViewModel | TModel | HttpResponse<TModel> | null> {
    // Check if a response is already available in the cache and just returns it
    // if found.
    const cachedResponseEntry = this.remoteCallCache?.get<TViewModel, TModel>(remoteCall);
    if (cachedResponseEntry) {
      // NOTE: We get a response from the cache, in order to make
      // Angular change detection working fine we provide the cached
      // response asynchrounsly avoiding changing the value while
      // the detection is running!
      return of(cachedResponseEntry).pipe(observeOn(asyncScheduler)) as Observable<
        TViewModel | TModel
      >;
    }

    return (
      of(remoteCall)
        // Create an http request from the remote call.
        .pipe(
          map((call: RemoteCallWithReportProgress<TViewModel, TModel>) => {
            const httpRequest = new HttpRequest(
              call.method,
              `${call.baseUrl}${call.relativePath}`,
              call.getBody(),
              {
                withCredentials: call.withCredentials,
                responseType: call.responseType,
                params: call.getQuery(),
                headers: call.getHeaders(),
                reportProgress: call.reportProgress || false,
                context: call.getContext(),
              },
            );

            return { httpRequest, call } as HttpData<TViewModel, TModel>;
          }),
          // Performs the http request and propagate the remote call.
          concatMap(({ httpRequest, call }: HttpDataWithReportProgress<TViewModel, TModel>) => {
            let request$ = this.httpClient.request(httpRequest.method, httpRequest.url, {
              body: httpRequest.body,
              headers: httpRequest.headers,
              reportProgress: httpRequest.reportProgress,
              observe: call.reportProgress ? 'events' : 'response',
              params: httpRequest.params,
              responseType: httpRequest.responseType,
              withCredentials: httpRequest.withCredentials,
              context: httpRequest.context,
            });

            // Check if we need to setup a request retry.
            const shouldSetupRequestRetry =
              Number.isFinite(call.retryAttemptCount) && call.retryAttemptCount > 0;
            if (shouldSetupRequestRetry) {
              request$ = request$.pipe(
                retryWhen((notifiers: Observable<HttpResponse<TModel>>) =>
                  notifiers.pipe(
                    concatMap((response: HttpResponse<TModel>, index: number) => {
                      // If the all the attempts has been tried or the request is not failed with status code zero forward the error...
                      if (!response || response.status !== 0 || index > call.retryAttemptCount) {
                        return throwError(response);
                      }
                      // ...otherwise execute the next attempt after a specified amount of time.
                      return of(response).pipe(delay(call.retryDelay));
                    }),
                  ),
                ),
              );
            }

            // Finally propagate the remote call along with the request stream.
            return request$.pipe(
              map((httpResponse: HttpResponse<TModel>) => ({
                httpResponse,
                call,
              })),
            );
          }),
          // Finally let's perform the mapping to get the response slice that's actually needed.
          map(({ httpResponse, call }) => {
            console.log(httpResponse);
            /**
             * Da rifattorizzare
             * al momento se progress ti dà la response solo se è ok
             */
            if (call.reportProgress) {
              if (
                (httpResponse.type as HttpEventType) === HttpEventType.ResponseHeader &&
                httpResponse.status !== HttpStatusCode.Ok
              ) {
                return null;
              }
              return httpResponse;
            }

            const model = call.contentProperty
              ? this.objectExtensionsService.getObjectValue<TModel>(
                  httpResponse,
                  call.contentProperty,
                )
              : (httpResponse as HttpResponse<TModel>);

            // Update the remote calls cache.
            if (this.remoteCallCache) {
              this.remoteCallCache.put<TViewModel, TModel>(call, model as TModel);
            }

            return (
              remoteCall.trasformer?.toViewModel(model as TModel) || (model as HttpResponse<TModel>)
            );
          }),
        )
    );
  }
}

export abstract class Singleton {
  private static instances = new Map<object, unknown>();

  static getInstance<T>(this: new () => T): T {
    if (!Singleton.instances.has(this)) {
      Singleton.instances.set(this, new this());
      console.debug(`[Singleton] Created instance of ${this.name}`);
    }
    return Singleton.instances.get(this) as T;
  }
}

