})
export class AccordionComponent implements AfterViewInit {
  @ViewChild('contentContainer', { read: ViewContainerRef, static: true })
  contentContainer?: ViewContainerRef;
  @ContentChild(TemplateRef) projectedContent?: TemplateRef<unknown>;
  @Input() useIcons = false;
  @Input() title: string = '';
  @Input() iconTitle?: string;
  @Input() id: string = '';
  @Input() expanded: boolean = false;
  @Output() toggleAccordion = new EventEmitter<boolean>();
  @Input() iconName?: string;
  @Input() iconColor?: string;
  @Input() icons?: Icon[];

  IconSize = IconSize;

  trackByIcon(_: number, icon: Icon): string {
    return icon.iconName ?? 'default-icon';
  }

  useDynamicContent = false;

  constructor(private cdr: ChangeDetectorRef) {}

  ngAfterViewInit(): void {
    // Se il componente viene utilizzato in remoto, il contenitore dinamico è abilitato
    this.useDynamicContent = !this.projectedContent && !this.contentContainer?.createEmbeddedView;
    if (
      this.useDynamicContent &&
      this.contentContainer &&
      this.projectedContent &&
      this.contentContainer?.createEmbeddedView
    ) {
      // Inseriamo il contenuto dinamico nel ViewContainerRef
      this.contentContainer?.createEmbeddedView(this.projectedContent);
    }
    if (this.expanded) {
      this.toggle(this.expanded);
    }
  }

  toggle(expanded?: boolean) {
    const element = document.getElementById('collapse1b-' + this.id);
    this.expanded = expanded || !this.expanded;

    if (expanded) {
      element?.classList.add('show');
    }

    element?.addEventListener('transitionend', () => {
      if (!this.expanded && element.className.includes('show')) {
        element.classList.remove('show');
      } else if (this.expanded && !element.className.includes('show')) {
        element.classList.add('show');
      }
      this.cdr.detectChanges();
    });
  }
}

