@Component({
  selector: 'app-rc-accordion-v2',
  standalone: true,
  imports: [CommonModule, HttpClientModule, IconComponent],
  styleUrl: './accordion-v2.component.scss',
  templateUrl: './accordion-v2.component.html',
})
export class AccordionVersion2Component implements AfterViewInit, OnDestroy {
  @ViewChild('contentContainer', { read: ViewContainerRef, static: true })
  contentContainer?: ViewContainerRef;

  @Input() internalProjectedContent?: TemplateRef<unknown>;

  @Input() id: string = '';
  @Input() expanded: boolean = false;

  @Output() toggleAccordion = new EventEmitter<boolean>();

  @Input() useIcons = false;
  @Input() title: string = '';
  @Input() iconTitle?: string;
  @Input() iconName?: string;
  @Input() iconColor?: string;
  @Input() icons?: Icon[];

  useDynamicContent = false;

  IconSize = IconSize;

  private viewRef?: EmbeddedViewRef<unknown>;

  constructor(private cdr: ChangeDetectorRef) {}

  trackByIcon(_: number, icon: Icon): string {
    return icon.iconName ?? 'default-icon';
  }

  ngAfterViewInit(): void {
    // Se il componente viene utilizzato in remoto, il contenitore dinamico è abilitato
    this.useDynamicContent =
      !this.internalProjectedContent && !this.contentContainer?.createEmbeddedView;
    console.log(this.internalProjectedContent, 'internalProjectedContent');
    // monta il contenuto se parte già aperto
    if (this.expanded) {
      this.mountTemplate();
      this.cdr.detectChanges();
    }
  }

  toggle(expanded?: boolean) {
    const element = document.getElementById('collapse1b-' + this.id);
    this.expanded = typeof expanded === 'boolean' ? expanded : !this.expanded;
    this.toggleAccordion.emit(this.expanded);

    if (this.expanded) {
      element?.classList.add('show');
    }

    element?.addEventListener('transitionend', () => {
      if (!this.expanded && element.className.includes('show')) {
        element.classList.remove('show');
      } else if (this.expanded && !element.className.includes('show')) {
        element.classList.add('show');
      }
      this.cdr.detectChanges();
    });

    if (this.expanded) {
      // quando apro, monto (se non già montato)
      this.mountTemplate();
    } else {
      // quando chiudo, distruggo la view del contenuto
      this.unmountTemplate();
    }

    this.cdr.detectChanges();
  }

  private mountTemplate() {
    if (!this.contentContainer || !this.internalProjectedContent) return;

    // se già montato, non duplicare
    if (this.viewRef) return;

    this.contentContainer.clear();
    this.viewRef = this.contentContainer.createEmbeddedView(this.internalProjectedContent, {
      expanded: this.expanded,
    });
  }

  private unmountTemplate() {
    this.viewRef?.destroy();
    this.viewRef = undefined;
    this.contentContainer?.clear();
  }

  ngOnDestroy(): void {
    this.unmountTemplate();
  }
}

