    this.buttonAddInjector = Injector.create({
      providers: [{ provide: 'buttonAdd', useValue: () => this.onButtonCallback() }],
    });
    this.filterInjector = Injector.create({
      providers: [{ provide: 'filter', useValue: () => this.onFilterCallback() }],
