  onButtonCallback(): void {
    this.buttonCallback.emit();
  }
  onFilterCallback(): void {
    this.filterCallback.emit();
  }
  onSearchCallback(value: unknown): void {
    this.searchCallback.emit(value);
  }

  handleClickFilter() {
    if (this.onClickFilter) {
      this.onClickFilter();
    }
  }
}

